import { test, expect } from '@playwright/test';

test.describe('Task Edit Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should successfully edit an existing task by clicking Edit button', async ({ page }) => {
    // Verify initial task list is displayed
    const taskList = page.getByRole('region', { name: /tasks/i });
    await expect(taskList).toBeVisible();

    // Verify Edit button is present for the first task
    const editButton = page.getByRole('button', { name: /edit/i });
    await expect(editButton).toBeVisible();

    // Click Edit button on the first task
    await editButton.click();

    // Verify edit form is visible
    const editForm = page.getByRole('dialog', { name: /edit task/i });
    await expect(editForm).toBeVisible();

    // Verify task title input is present and has initial value
    const taskTitleInput = page.getByLabel(/task title/i);
    await expect(taskTitleInput).toBeVisible();
    await expect(taskTitleInput).toHaveValue('Initial Task Title');

    // Verify task description input is present
    const taskDescriptionInput = page.getByLabel(/task description/i);
    await expect(taskDescriptionInput).toBeVisible();

    // Verify save button is present
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Verify update button is present
    const updateButton = page.getByRole('button', { name: /update/i });
    await expect(updateButton).toBeVisible();

    // Verify delete button is present
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeVisible();

    // Verify edit form is closed
    await expect(editForm).not.toBeVisible();

    // Verify task list is still displayed
    await expect(taskList).toBeVisible();

    // Verify task title input has updated value
    await expect(taskTitleInput).toHaveValue('Updated Task Title');

    // Verify task description input has updated value
    await expect(taskDescriptionInput).toHaveValue('Updated Task Description');

    // Verify save button is now disabled
    await expect(saveButton).toBeDisabled();

    // Verify update button is now enabled
    await expect(updateButton).toBeEnabled();

    // Verify delete button is now enabled
    await expect(deleteButton).toBeEnabled();

    // Click save button
    await saveButton.click();

    // Verify success message is displayed
    const successMessage = page.getByText(/task updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify task list is updated with new values
    const taskItem = page.getByText(/updated task title/i);
    await expect(taskItem).toBeVisible();

    // Verify edit form is closed
    await expect(editForm).not.toBeVisible();
  });

  test('should handle empty task title and description gracefully', async ({ page }) => {
    // Verify initial task list is displayed
    const taskList = page.getByRole('region', { name: /tasks/i });
    await expect(taskList).toBeVisible();

    // Click Edit button on the first task
    const editButton = page.getByRole('button', { name: /edit/i });
    await editButton.click();

    // Verify edit form is visible
    const editForm = page.getByRole('dialog', { name: /edit task/i });
    await expect(editForm).toBeVisible();

    // Verify task title input is present
    const taskTitleInput = page.getByLabel(/task title/i);
    await expect(taskTitleInput).toBeVisible();

    // Verify task description input is present
    const taskDescriptionInput = page.getByLabel(/task description/i);
    await expect(taskDescriptionInput).toBeVisible();

    // Verify save button is present
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Verify update button is present
    const updateButton = page.getByRole('button', { name: /update/i });
    await expect(updateButton).toBeVisible();

    // Verify delete button is present
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeVisible();

    // Verify edit form is closed
    await expect(editForm).not.toBeVisible();

    // Verify task list is still displayed
    await expect(taskList).toBeVisible();

    // Verify task title input is empty
    await expect(taskTitleInput).toHaveValue('');

    // Verify task description input is empty
    await expect(taskDescriptionInput).toHaveValue('');

    // Verify save button is now enabled
    await expect(saveButton).toBeEnabled();

    // Verify update button is now enabled
    await expect(updateButton).toBeEnabled();

    // Verify delete button is now enabled
    await expect(deleteButton).toBeEnabled();

    // Click save button
    await saveButton.click();

    // Verify success message is displayed
    const successMessage = page.getByText(/task updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify task list is updated with empty values
    const taskItem = page.getByText(/empty task title/i);
    await expect(taskItem).toBeVisible();

    // Verify edit form is closed
    await expect(editForm).not.toBeVisible();
  });
});
